CREATE TABLE knowledge_outbox(id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,aggregate_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,event_type VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,payload_json JSON NOT NULL,status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'PENDING',retry_count INT UNSIGNED NOT NULL DEFAULT 0,next_retry_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),claimed_at DATETIME(6) NULL,published_at DATETIME(6) NULL,last_error VARCHAR(1000) NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),INDEX idx_knowledge_outbox_dispatch(status,next_retry_at));
